const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".tb,.tf{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;color:var(--ink);font:13px/1.4 -apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",sans-serif}\n.tb *,.tf *{box-sizing:border-box}\n.tb button,.tf button{font:inherit;color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}\n.tb button:focus-visible,.tf button:focus-visible,.tf .in:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.tb button:disabled,.tf button:disabled{opacity:.4;cursor:default}\n\n/* \u770b\u677f\uff1a\u9ed8\u8ba4\uff083x6 / \u901a\u7528\uff09\u5355\u5217 */\n.tb{display:grid;gap:8px;padding:10px;grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto minmax(0,1fr) auto;grid-template-areas:\"head\" \"tabs\" \"main\" \"add\"}\n.head{grid-area:head;display:flex;flex-direction:column;gap:6px;min-width:0}\n.tabs{grid-area:tabs;display:flex;gap:4px;min-width:0}\n.main{grid-area:main;display:flex;flex-direction:column;gap:6px;min-height:0;min-width:0}\n.add{grid-area:add}\n.hl{display:flex;align-items:baseline;gap:4px 8px;flex-wrap:wrap}\n.ht{font-size:17px;font-weight:700;letter-spacing:.02em}\n.hs{font-size:11.5px;color:var(--muted)}\n.prog{display:flex;height:6px;border-radius:99px;background:var(--line);overflow:hidden}\n.pg{flex-basis:0;flex-shrink:1;min-width:0}\n.pg.done{background:var(--accent)}\n.pg.doing{background:var(--accent-alt)}\n.pg.todo{background:transparent}\n\n.tab{flex:1 1 0;min-width:0;display:flex;align-items:center;justify-content:center;gap:5px;padding:4px;min-height:34px;border-radius:10px;border:1px solid var(--line);background:transparent;white-space:nowrap}\n.tab .tc{font-weight:700;font-variant-numeric:tabular-nums}\n.tab.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n\n.add{display:flex;align-items:center;justify-content:center;gap:6px;min-height:36px;padding:0 14px;border:0;border-radius:10px;background:var(--accent);color:var(--on-accent);font-weight:600}\n.add .plus{font-size:16px;line-height:1}\n\n.tools{display:flex;gap:4px;overflow-x:auto;flex:none;padding-bottom:2px}\n.fc{flex:none;min-height:26px;max-width:150px;padding:2px 10px;border:1px solid var(--line);border-radius:99px;background:transparent;font-size:11.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.fc.on{background:var(--soft);border-color:var(--accent);font-weight:600}\n.note{flex:none;font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.list{flex:1 1 auto;min-height:0;position:relative;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:6px;padding:1px 2px 2px 1px}\n.empty{margin:auto;text-align:center;color:var(--muted);font-size:12px;line-height:1.55;padding:10px 6px;overflow-wrap:anywhere}\n\n/* \u4efb\u52a1\u884c */\n.row{flex:none;display:grid;grid-template-columns:minmax(0,1fr) auto;background:var(--panel-paper);border:1px solid var(--line);border-radius:10px;overflow:hidden}\n.row.sel{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent)}\n.rowmain{appearance:none;-webkit-appearance:none;border:0;background:transparent;text-align:left;display:flex;gap:7px;align-items:flex-start;min-width:0;padding:7px 8px}\n.rank{flex:none;width:19px;height:19px;margin-top:1px;border-radius:50%;border:1.5px solid var(--line);color:var(--muted);font-size:10.5px;font-weight:700;display:grid;place-items:center}\n.rank.top{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.txt{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}\n.ttl{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;line-height:1.35}\n.row.sel .ttl{display:block;-webkit-line-clamp:unset}\n.meta{display:flex;flex-wrap:wrap;align-items:center;gap:3px 5px;font-size:10.5px;color:var(--muted);min-width:0}\n.chip{max-width:100%;padding:0 7px;border-radius:99px;background:var(--soft);color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.due{white-space:nowrap}\n.due.soon{color:var(--ink);font-weight:600}\n.due.over{color:var(--accent);font-weight:700}\n.adv{appearance:none;-webkit-appearance:none;border:0;border-left:1px solid var(--line);background:var(--soft);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;min-width:36px;padding:0 8px;font-size:11px}\n.adv .ag{font-size:13px;line-height:1.1}\n.bar{grid-column:1 / -1;display:flex;flex-wrap:wrap;gap:4px;padding:6px 8px 8px;border-top:1px dashed var(--line)}\n.bar button{min-height:28px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--panel-paper));font-size:11.5px;white-space:nowrap}\n.bar .ed{margin-left:auto}\n\n/* \u8868\u5355 */\n.tf{display:grid;gap:8px;padding:12px;grid-template-rows:auto minmax(0,1fr) auto}\n.fh{display:flex;align-items:center;gap:10px}\n.ft{font-size:16px;font-weight:700}\n.fb{min-height:0;overflow-y:auto;overflow-x:hidden;display:grid;gap:10px;align-content:start;grid-template-columns:minmax(0,1fr);padding:2px}\n.fld{display:flex;flex-direction:column;gap:4px;min-width:0}\n.fl{font-size:11.5px;color:var(--muted)}\n.in{width:100%;min-width:0;min-height:34px;padding:6px 9px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit}\n.in::placeholder{color:var(--muted)}\n.qrow{display:flex;flex-wrap:wrap;gap:4px}\n.qc{min-height:26px;max-width:100%;padding:2px 10px;border:1px solid var(--line);border-radius:99px;background:transparent;font-size:11.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.qc.on{background:var(--soft);border-color:var(--accent);font-weight:600}\n.seg{display:flex;gap:4px}\n.sg{flex:1 1 0;min-width:0;min-height:32px;padding:0 4px;border:1px solid var(--line);border-radius:9px;background:transparent;white-space:nowrap}\n.sg.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.err{padding:5px 8px;border:1px dashed var(--accent);border-radius:8px;font-size:12px;color:var(--ink)}\n.ff{display:flex;align-items:center;gap:6px}\n.ff .grow{flex:1}\n.btn{min-height:34px;padding:0 12px;border:1px solid var(--line);border-radius:9px;background:var(--button-paper,var(--panel-paper));white-space:nowrap}\n.btn.pri{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.btn.danger{border-style:dashed}\n.btn.danger.arm{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n\n/* 194 x 194 */\n[data-size=\"3x3\"] .tb{padding:8px;gap:6px;grid-template-columns:minmax(0,1fr) 38px;grid-template-rows:auto minmax(0,1fr);grid-template-areas:\"tabs add\" \"main main\"}\n[data-size=\"3x3\"] .head{display:none}\n[data-size=\"3x3\"] .add{padding:0}\n[data-size=\"3x3\"] .add .lbl{display:none}\n[data-size=\"3x3\"] .add .plus{font-size:20px}\n[data-size=\"3x3\"] .tf{padding:8px;gap:6px;grid-template-rows:minmax(0,1fr) auto}\n[data-size=\"3x3\"] .fh{display:none}\n[data-size=\"3x3\"] .btn{padding:0 9px;min-height:32px}\n\n/* 3 \u5217\u5bbd\u7684\u5361\u7247\uff1a\u6807\u7b7e\u4e0a\u4e0b\u53e0\u653e\uff0c\u884c\u5185\u53ea\u663e\u793a\u56fe\u6807 */\n[data-size=\"3x3\"] .tab,[data-size=\"3x6\"] .tab{flex-direction:column;gap:0;min-height:36px;padding:3px 2px;font-size:11px;line-height:1.25}\n[data-size=\"3x3\"] .tab .tc,[data-size=\"3x6\"] .tab .tc{font-size:13px}\n[data-size=\"3x3\"] .adv .al,[data-size=\"3x6\"] .adv .al{display:none}\n[data-size=\"3x3\"] .rowmain,[data-size=\"3x6\"] .rowmain{padding:6px 6px;gap:6px}\n[data-size=\"3x3\"] .adv,[data-size=\"3x6\"] .adv{min-width:32px;padding:0 6px}\n[data-size=\"3x3\"] .bar,[data-size=\"3x6\"] .bar{padding:5px 6px 6px}\n\n/* 404 x 194\uff1a\u5de6\u4fa7\u7ad6\u6392\u6807\u7b7e\uff0c\u53f3\u4fa7\u4efb\u52a1 */\n[data-size=\"6x3\"] .tb{padding:8px;gap:8px;grid-template-columns:92px minmax(0,1fr);grid-template-rows:minmax(0,1fr) auto;grid-template-areas:\"tabs main\" \"add main\"}\n[data-size=\"6x3\"] .head{display:none}\n[data-size=\"6x3\"] .tabs{flex-direction:column}\n[data-size=\"6x3\"] .tab{flex:1 1 0;min-height:0;justify-content:space-between;padding:0 10px}\n[data-size=\"6x3\"] .tf{padding:8px;gap:6px;grid-template-rows:minmax(0,1fr) auto}\n[data-size=\"6x3\"] .fh{display:none}\n[data-size=\"6x3\"] .fb{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px 12px}\n[data-size=\"6x3\"] .err{grid-column:1 / -1}\n[data-size=\"6x3\"] .btn{min-height:32px}\n\n/* 194 x 404 */\n[data-size=\"3x6\"] .tb{gap:8px}\n[data-size=\"3x6\"] .add{width:100%}\n[data-size=\"3x6\"] .tf{padding:10px}\n\n/* 404 x 404\uff1a\u9876\u90e8\u6807\u9898 + \u8fdb\u5ea6\uff0c\u4e0b\u9762\u662f\u6807\u7b7e\u548c\u957f\u5217\u8868 */\n[data-size=\"6x6\"] .tb{padding:14px;gap:10px;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto auto minmax(0,1fr);grid-template-areas:\"head add\" \"tabs tabs\" \"main main\"}\n[data-size=\"6x6\"] .head{align-self:center}\n[data-size=\"6x6\"] .add{align-self:start}\n[data-size=\"6x6\"] .ht{font-size:20px}\n[data-size=\"6x6\"] .tab{min-height:38px}\n[data-size=\"6x6\"] .rowmain{padding:9px 10px;gap:9px}\n[data-size=\"6x6\"] .tf{padding:16px;gap:10px}\n[data-size=\"6x6\"] .fb{gap:12px}\n";
const ST=[
  {k:'todo',n:'待做',go:'开始',g:'▶'},
  {k:'doing',n:'进行中',go:'完成',g:'✓'},
  {k:'done',n:'已完成',go:'重开',g:'↺'}
];
const WD=['日','一','二','三','四','五','六'];
function p2(n){return n<10?'0'+n:''+n}
function pd(s){
  const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');
  if(!m)return null;
  const d=new Date(+m[1],+m[2]-1,+m[3]);
  return isNaN(d.getTime())?null:d;
}
function fd(d){return d.getFullYear()+'-'+p2(d.getMonth()+1)+'-'+p2(d.getDate())}
function addDays(s,n){const d=pd(s);d.setDate(d.getDate()+n);return fd(d)}
function diffDays(a,b){return Math.round((pd(a).getTime()-pd(b).getTime())/86400000)}
function md(s){const d=pd(s);return d?p2(d.getMonth()+1)+'/'+p2(d.getDate()):''}
function weekOf(today){
  const d=pd(today);
  const a=addDays(today,-((d.getDay()+6)%7));
  return {a:a,b:addDays(a,6)};
}
function stOf(k){for(let i=0;i<ST.length;i++){if(ST[i].k===k)return ST[i]}return ST[0]}
function nextOf(k){return k==='todo'?'doing':(k==='doing'?'done':'todo')}
function short(s){s=String(s||'');return s.length>10?s.slice(0,10)+'…':s}

function tasksOf(s){
  const a=s&&Array.isArray(s.tasks)?s.tasks:[];
  return a.filter(function(t){return t&&t.id&&typeof t.title==='string'}).map(function(t){
    return ST.some(function(x){return x.k===t.status})?t:{...t,status:'todo'};
  });
}
function projectsOf(tasks){
  const o=[];
  tasks.forEach(function(t){if(t.project&&o.indexOf(t.project)<0)o.push(t.project)});
  return o;
}
function colOf(tasks,st,proj){
  return tasks.filter(function(t){return t.status===st&&(!proj||t.project===proj)});
}
function dueInfo(t,today){
  if(!t.due||!pd(t.due))return null;
  const n=diffDays(t.due,today);
  if(n<0)return {text:'⚠ 逾期'+(-n)+'天',cls:'over'};
  if(n===0)return {text:'今天截止',cls:'soon'};
  if(n===1)return {text:'明天截止',cls:'soon'};
  return {text:md(t.due)+' 周'+WD[pd(t.due).getDay()],cls:''};
}

/* 在某一列（可带项目筛选）里调整优先级：top 置顶 / up 前移 / down 后移 */
function reorder(tasks,id,mode,st,proj){
  const vis=colOf(tasks,st,proj).map(function(t){return t.id});
  const i=vis.indexOf(id);
  if(i<0)return tasks;
  const out=tasks.slice();
  const at=function(x){return out.findIndex(function(t){return t.id===x})};
  if(mode==='top'){
    if(i===0)return tasks;
    const f=at(id),to=at(vis[0]);
    const it=out.splice(f,1)[0];
    out.splice(to,0,it);
    return out;
  }
  const j=mode==='up'?i-1:i+1;
  if(j<0||j>=vis.length)return tasks;
  const a=at(id),b=at(vis[j]);
  const tmp=out[a];out[a]=out[b];out[b]=tmp;
  return out;
}
/* 换状态：排到目标列的末尾 */
function shift(tasks,id,to,today){
  const t=tasks.find(function(x){return x.id===id});
  if(!t)return tasks;
  const nt={...t,status:to,doneAt:to==='done'?today:''};
  return tasks.filter(function(x){return x.id!==id}).concat([nt]);
}

function h(c,tag,attrs,kids){
  const k=(kids||[]).filter(function(x){return x!==null&&x!==undefined&&x!==false&&x!==''});
  return c.el(tag,attrs||{},...k);
}
function btn(c,cls,label,onclick,disabled){
  const a={type:'button',class:cls,onclick:onclick};
  if(disabled)a.disabled=true;
  return h(c,'button',a,[label]);
}
/* 基于最新数据修改任务列表；note 是操作后的一行反馈 */
function run(c,fn,note,keepSel){
  c.ui.note=note||'';
  if(!keepSel)c.ui.sel=null;
  c.ui.confirmDel=false;
  return c.update(function(s){return {...s,tasks:fn(tasksOf(s))}}).catch(function(){});
}
function openNew(c){
  const ui=c.ui;
  ui.draft={id:'',nid:c.uid(),title:'',project:'',due:'',status:ui.tab||'todo'};
  ui.view='form';ui.err='';ui.confirmDel=false;
  c.redraw();
}
function openEdit(c,t){
  const ui=c.ui;
  ui.draft={id:t.id,nid:t.id,title:t.title,project:t.project||'',due:t.due||'',status:t.status};
  ui.view='form';ui.err='';ui.confirmDel=false;
  c.redraw();
}

function barEl(c,t,i,n,v){
  const mv=function(x){
    return btn(c,'mv','→ '+x.n,function(){
      run(c,function(a){return shift(a,t.id,x.k,v.today)},'「'+short(t.title)+'」已移到'+x.n);
    });
  };
  const items=[
    btn(c,'','⤒ 置顶',function(){
      run(c,function(a){return reorder(a,t.id,'top',t.status,v.proj)},'',true);
    },i===0),
    btn(c,'','↑ 前移',function(){
      run(c,function(a){return reorder(a,t.id,'up',t.status,v.proj)},'',true);
    },i===0),
    btn(c,'','↓ 后移',function(){
      run(c,function(a){return reorder(a,t.id,'down',t.status,v.proj)},'',true);
    },i===n-1)
  ];
  ST.forEach(function(x){if(x.k!==t.status)items.push(mv(x))});
  items.push(btn(c,'ed','✎ 编辑',function(){openEdit(c,t)}));
  return h(c,'div',{class:'bar'},items);
}

function rowEl(c,t,i,n,v){
  const ui=c.ui,sel=ui.sel===t.id,today=v.today;
  const meta=[];
  if(t.project)meta.push(h(c,'span',{class:'chip'},[t.project]));
  if(t.status==='done'){
    if(t.doneAt)meta.push(h(c,'span',{class:'due'},['完成于 '+md(t.doneAt)]));
  }else{
    const di=dueInfo(t,today);
    if(di)meta.push(h(c,'span',{class:'due '+di.cls},[di.text]));
  }
  const s=stOf(t.status),nx=stOf(nextOf(t.status));
  const main=h(c,'button',{
    type:'button',class:'rowmain','aria-expanded':sel?'true':'false',
    onclick:function(){ui.sel=sel?null:t.id;ui.confirmDel=false;c.redraw()}
  },[
    h(c,'span',{class:'rank'+(i===0&&t.status!=='done'?' top':'')},[t.status==='done'?'✓':String(i+1)]),
    h(c,'span',{class:'txt'},[
      h(c,'span',{class:'ttl'},[t.title]),
      meta.length?h(c,'span',{class:'meta'},meta):null
    ])
  ]);
  const adv=h(c,'button',{
    type:'button',class:'adv','aria-label':s.go+'，移到'+nx.n,
    onclick:function(){
      run(c,function(a){return shift(a,t.id,nx.k,today)},'「'+short(t.title)+'」已移到'+nx.n);
    }
  },[
    h(c,'span',{class:'ag'},[s.g]),
    h(c,'span',{class:'al'},[s.go])
  ]);
  return h(c,'div',{class:'row'+(sel?' sel':'')},[main,adv,sel?barEl(c,t,i,n,v):null]);
}

function emptyText(tab,total,proj){
  if(!total)return '这周还没有任务。点「＋」写下第一件事。';
  const n=stOf(tab).n;
  if(proj)return '「'+proj+'」在「'+n+'」里没有任务';
  return tab==='todo'?'待做里没有任务':(tab==='doing'?'还没有进行中的任务':'还没有完成的任务');
}

function boardEl(c){
  const ui=c.ui,today=c.day();
  const tasks=tasksOf(c.state);
  const canF=c.size==='3x6'||c.size==='6x6';
  const projs=projectsOf(tasks);
  if(ui.proj&&projs.indexOf(ui.proj)<0)ui.proj='';
  const proj=canF?(ui.proj||''):'';
  const v={today:today,proj:proj};
  const list=colOf(tasks,ui.tab,proj);
  const total=tasks.length;
  const cnt={},all={};
  ST.forEach(function(x){
    cnt[x.k]=colOf(tasks,x.k,proj).length;
    all[x.k]=tasks.filter(function(t){return t.status===x.k}).length;
  });
  const wk=weekOf(today);

  const segs=total?['done','doing','todo'].map(function(k){
    const sp=h(c,'span',{class:'pg '+k},[]);
    sp.style.flexGrow=String(all[k]);
    return sp;
  }):[];
  const head=h(c,'div',{class:'head'},[
    h(c,'div',{class:'hl'},[
      h(c,'span',{class:'ht'},['本周任务']),
      h(c,'span',{class:'hs'},[md(wk.a)+' – '+md(wk.b)+(total?' · 已完成 '+all.done+'/'+total:'')])
    ]),
    h(c,'div',{class:'prog'},segs)
  ]);

  const tabs=h(c,'div',{class:'tabs'},ST.map(function(x){
    return h(c,'button',{
      type:'button',class:'tab'+(ui.tab===x.k?' on':''),'aria-pressed':ui.tab===x.k?'true':'false',
      onclick:function(){ui.tab=x.k;ui.sel=null;ui.note='';ui.scroll=0;c.redraw()}
    },[
      h(c,'span',{class:'tl'},[x.n]),
      h(c,'span',{class:'tc'},[String(cnt[x.k])])
    ]);
  }));

  let tools=null;
  if(canF&&projs.length){
    const chip=function(label,val){
      return btn(c,'fc'+((ui.proj||'')===val?' on':''),label,function(){
        ui.proj=val;ui.sel=null;ui.scroll=0;c.redraw();
      });
    };
    tools=h(c,'div',{class:'tools'},[chip('全部项目','')].concat(projs.map(function(p){return chip(p,p)})));
  }
  const note=ui.note?h(c,'div',{class:'note',role:'status'},['✓ '+ui.note]):null;

  const rows=list.length
    ?list.map(function(t,i){return rowEl(c,t,i,list.length,v)})
    :[h(c,'div',{class:'empty'},[emptyText(ui.tab,total,proj)])];
  const listEl=h(c,'div',{class:'list'},rows);
  listEl.addEventListener('scroll',function(){ui.scroll=listEl.scrollTop});

  const add=h(c,'button',{type:'button',class:'add','aria-label':'添加任务',onclick:function(){openNew(c)}},[
    h(c,'span',{class:'plus'},['＋']),
