/* 重绘后恢复列表滚动位置，并让选中的行（含操作条）保持可见 */
function restoreScroll(c,list){
  const ui=c.ui;
  list.scrollTop=ui.scroll||0;
  if(!ui.sel||!list.clientHeight)return;
  const r=list.querySelector('.row.sel');
  if(!r)return;
  const top=r.offsetTop,bot=top+r.offsetHeight;
  if(bot>list.scrollTop+list.clientHeight)list.scrollTop=Math.min(top,bot-list.clientHeight);
  else if(top<list.scrollTop)list.scrollTop=top;
  ui.scroll=list.scrollTop;
}

function save(c){
  const ui=c.ui,d=ui.draft;
  if(!d)return;
  const title=String(d.title||'').trim();
  const project=String(d.project||'').trim();
  const due=d.due||'';
  if(!title){ui.err='请先填写任务名称';c.redraw();return}
  if(due&&!pd(due)){ui.err='截止日期格式不对，请重新选择或点「清除」';c.redraw();return}
  const id=d.id||d.nid,status=d.status,today=c.day();
  return c.commit(function(s){
    const all=tasksOf(s);
    const old=all.find(function(t){return t.id===id});
    let tasks;
    if(!old){
      tasks=all.concat([{id:id,title:title,project:project,due:due,status:status,doneAt:status==='done'?today:'',created:today}]);
    }else{
      tasks=all.map(function(t){return t.id===id?{...t,title:title,project:project,due:due}:t});
      if(old.status!==status)tasks=shift(tasks,id,status,today);
    }
    return {...s,tasks:tasks};
  },{...ui,tab:status,view:'board',draft:null,err:'',sel:null,confirmDel:false,scroll:0,note:'已保存「'+short(title)+'」'}).catch(function(){});
}

function removeDraft(c){
  const ui=c.ui,id=ui.draft&&ui.draft.id;
  if(!id)return;
  if(!ui.confirmDel){ui.confirmDel=true;c.redraw();return}
  return c.commit(function(s){
    return {...s,tasks:tasksOf(s).filter(function(t){return t.id!==id})};
  },{...ui,view:'board',draft:null,err:'',sel:null,confirmDel:false,note:'任务已删除'}).catch(function(){});
}

function formEl(c){
  const ui=c.ui,d=ui.draft,isEdit=!!d.id,today=c.day();
  const projs=projectsOf(tasksOf(c.state));
