    return btn(c,'qc'+(q[1]&&d.due===q[1]?' on':''),q[0],function(){d.due=q[1];c.redraw()});
  }));
  const seg=h(c,'div',{class:'seg'},ST.map(function(x){
    return btn(c,'sg'+(d.status===x.k?' on':''),x.n,function(){d.status=x.k;c.redraw()});
  }));

  const fields=[
