    btn(c,'btn pri','保存',function(){save(c)})
  ]);
  return h(c,'div',{class:'tf'},[
    h(c,'div',{class:'fh'},[btn(c,'btn','‹ 返回',back),h(c,'span',{class:'ft'},[isEdit?'编辑任务':'新任务'])]),
    h(c,'div',{class:'fb'},fields),
    foot
  ]);
}

function mount(ctx){
  const {root,ui}=ctx;
  if(!ui.tab)ui.tab='todo';
  if(!ui.view)ui.view='board';
  if(ui.view==='form'&&!ui.draft)ui.view='board';
  if(ui.view==='form'){root.append(formEl(ctx));return}
  const tb=boardEl(ctx);
  root.append(tb);
  const list=tb.querySelector('.list');
  if(list)restoreScroll(ctx,list);
}

